const routed = $json || {};
const whatsapp = routed.whatsapp || routed;
const media = routed.media || whatsapp.media || {};
const raw = whatsapp.raw || routed.raw || {};
const rawBody = raw.body || raw || {};
const rawData = rawBody.data || {};
const rawMessage = rawData.message || {};

function unwrapMessage(message) {
  let current = message || {};
  for (let i = 0; i < 5; i += 1) {
    if (current.ephemeralMessage?.message) current = current.ephemeralMessage.message;
    else if (current.viewOnceMessage?.message) current = current.viewOnceMessage.message;
    else if (current.viewOnceMessageV2?.message) current = current.viewOnceMessageV2.message;
    else if (current.documentWithCaptionMessage?.message) current = current.documentWithCaptionMessage.message;
    else break;
  }
  return current || {};
}

function compactObject(value) {
  if (!value || typeof value !== 'object') return value;
  const output = {};
  for (const [key, item] of Object.entries(value)) {
    if (item !== undefined && item !== null && item !== '') output[key] = item;
  }
  return output;
}

function buildEvolutionDownloadMessage({ key, rawMessage: message, rawData: data, imageMessage, documentMessage }) {
  const messagePayload = message && Object.keys(message).length > 0
    ? message
    : imageMessage
      ? { imageMessage }
      : documentMessage
        ? { documentMessage }
        : null;

  if (!messagePayload) return null;

  // Evolution getBase64FromMediaMessage expects a WhatsApp message envelope, not only imageMessage/documentMessage.
  // Passing only { imageMessage } makes some Evolution versions try to read message.message.ephemeralMessage and fail.
  return compactObject({
    key: key || data?.key,
    message: messagePayload,
    messageType: data?.messageType,
    messageTimestamp: data?.messageTimestamp,
    pushName: data?.pushName,
    status: data?.status,
    participant: data?.key?.participant || undefined,
    contextInfo: data?.contextInfo || undefined
  });
}

const inner = unwrapMessage(rawMessage);
const imageMessage = media.raw_image || inner.imageMessage || null;
const documentMessage = media.raw_document || inner.documentMessage || null;
const mediaMessage = buildEvolutionDownloadMessage({
  key: rawData.key,
  rawMessage,
  rawData,
  imageMessage,
  documentMessage
}) || routed.media_message || media.raw_image || media.raw_document || null;
const mimeType = String(media.mime_type || imageMessage?.mimetype || documentMessage?.mimetype || '').trim();
const filename = String(media.filename || imageMessage?.fileName || documentMessage?.fileName || 'comprovante.jpg').trim();
const caption = String(media.caption || imageMessage?.caption || documentMessage?.caption || whatsapp.message_text || routed.source?.raw_text || '').trim();
const serverUrl = String($env.EVOLUTION_API_URL || routed.evolution_api_url || whatsapp.evolution_api_url || rawBody.server_url || '').trim();
const apiKey = String($env.EVOLUTION_API_KEY || routed.evolution_api_key || whatsapp.evolution_api_key || rawBody.apikey || '').trim();

return [{ json: {
  ...routed,
  phone: whatsapp.phone || routed.phone,
  instance: whatsapp.instance || routed.instance || $env.EVOLUTION_INSTANCE_NAME || 'ACERTTAPAY',
  message_id: whatsapp.message_id || routed.source?.message_id || routed.message_id,
  message_text: whatsapp.message_text || routed.source?.raw_text || '',
  is_valid_user_message: whatsapp.is_valid_user_message !== false && whatsapp.can_reply !== false,
  conversation_state: routed.conversation?.state || null,
  media: {
    ...media,
    is_image: media.is_image === true,
    mime_type: mimeType || null,
    filename,
    caption: caption || null,
    raw_image: imageMessage || media.raw_image || null,
    raw_document: documentMessage || media.raw_document || null
  },
  media_message: mediaMessage,
  evolution_api_url: serverUrl,
  evolution_api_key: apiKey,
  source: routed.source || {
    channel: 'whatsapp',
    instance: whatsapp.instance,
    message_id: whatsapp.message_id,
    raw_text: whatsapp.message_text || caption
  },
  whatsapp,
  raw: raw || {}
}}];

const normalized = $('Normalize Routed Payload').first().json || {};
const text = normalized.message_text || normalized.source?.raw_text || '';
return [{ json: {
  phone: normalized.phone,
  source: {
    channel: 'whatsapp',
    instance: normalized.instance,
    message_id: normalized.message_id,
    raw_text: text
  },
  reply: {
    text,
    raw_text: text,
    intent: /(cancelar|cancela|cancelado|desistir|desisto|desisti|descartar|descarta|parar|para|sair|voltar|deixa pra la|deixa para la|esquece|nao quero|não quero)/i.test(text) ? 'cancel_receipt_purchase' : undefined,
    confirm: /^(sim|s|confirmar|confirmo|ok|pode|isso)$/i.test(String(text || '').trim()) ? true : undefined
  }
}}];

const normalized = $('Normalize Routed Payload').first().json || {};
const download = $json || {};
function findBase64(value) {
  if (!value) return '';
  if (typeof value === 'string') {
    const clean = value.replace(/^data:[^;]+;base64,/i, '').replace(/\s+/g, '').trim();
    return clean.length > 80 ? clean : '';
  }
  if (Array.isArray(value)) {
    for (const item of value) { const found = findBase64(item); if (found) return found; }
    return '';
  }
  if (typeof value === 'object') {
    const keys = ['base64', 'base64Message', 'base64Data', 'file', 'data', 'media', 'buffer', 'content', 'response', 'result'];
    for (const key of keys) { const found = findBase64(value[key]); if (found) return found; }
  }
  return '';
}
function summarizeDownloadError(value) {
  return String(
    value?.error?.message
    || value?.error?.description
    || value?.response?.message
    || value?.message
    || value?.rawErrorMessage
    || ''
  ).slice(0, 600);
}
function mediaShape(message) {
  const payload = message || {};
  const inner = payload.message || payload;
  return {
    has_key: Boolean(payload.key),
    has_message: Boolean(payload.message),
    message_keys: Object.keys(inner || {}).slice(0, 12),
    has_image: Boolean(inner?.imageMessage || payload.imageMessage),
    has_document: Boolean(inner?.documentMessage || payload.documentMessage)
  };
}
const hasDownloadError = Boolean(download.error || download.message?.error || download.status === 'error' || download.status >= 400 || download.code === 'ECONNREFUSED');
const base64 = hasDownloadError ? '' : findBase64(download);
const debug = {
  evolution_api_url_configured: Boolean(String(normalized.evolution_api_url || '').trim()),
  instance: normalized.instance || null,
  download_status: download.status || download.statusCode || null,
  download_error: summarizeDownloadError(download) || null,
  media_message: mediaShape(normalized.media_message),
  mime_type: normalized.media?.mime_type || null,
  filename: normalized.media?.filename || null
};
if (!base64) {
  return [{ json: {
    ok: false,
    media_download_ok: false,
    code: 'RECEIPT_IMAGE_MEDIA_DOWNLOAD_FAILED',
    whatsapp: { text: 'Recebi a imagem, mas não consegui baixar o arquivo da Evolution agora. Confere a conexão com a Evolution e tenta reenviar o comprovante.' },
    send_by_orchestrator: true,
    debug
  }}];
}
return [{ json: {
  ok: true,
  media_download_ok: true,
  phone: normalized.phone,
  image: {
    base64,
    mime_type: normalized.media?.mime_type || 'image/jpeg',
    filename: normalized.media?.filename || 'comprovante.jpg'
  },
  caption: normalized.media?.caption || normalized.message_text || '',
  source: {
    channel: 'whatsapp',
    instance: normalized.instance,
    message_id: normalized.message_id,
    raw_text: normalized.media?.caption || normalized.message_text || '',
    media_debug: debug
  }
}}];

const result = $json || {};
return [{ json: {
  ...result,
  ok: result.ok === true,
  workflow_key: '1.4',
  outbound_text: result.whatsapp?.text || result.message || 'Pedido processado no AcerttaPay.',
  send_by_orchestrator: true,
  whatsapp: { ...(result.whatsapp || {}), text: result.whatsapp?.text || result.message || 'Pedido processado no AcerttaPay.' }
}}];
